(7173585, 1100648, 174613, '<td valign="top">Beautiful colors very true to life.   =10= for sure</td>', 'Beautiful colors very true to life.   =10= for sure', '2014-02-09 20:27:16.000000', NULL, 1),
(7173825, 1101233, 114285, '<td valign="top">Stunning image, love the frame!</td>', 'Stunning image, love the frame!', '2014-02-10 01:48:23.000000', NULL, 1),
(7173826, 1101312, 114285, '<td valign="top">Now that is minimal for sure, not like a lot of images on here, love the PP!</td>', 'Now that is minimal for sure, not like a lot of images on here, love the PP!', '2014-02-10 01:49:15.000000', NULL, 1),
(7173827, 1101237, 114285, '<td valign="top">Stunning perspective, with the added footprints, well done.</td>', 'Stunning perspective, with the added footprints, well done.', '2014-02-10 01:50:07.000000', NULL, 1),
(7173829, 1101402, 114285, '<td valign="top">Lovely shot, don''t forget to straighten the horizon next time :)</td>', 'Lovely shot, don''t forget to straighten the horizon next time :)', '2014-02-10 01:51:32.000000', NULL, 1),
(7173830, 1100804, 114285, '<td valign="top">gorgeous shot, would of liked it if the person was still walking though, but that''s just me, she seems to be staring at nothing!</td>', 'gorgeous shot, would of liked it if the person was still walking though, but that''s just me, she seems to be staring at nothing!', '2014-02-10 01:52:42.000000', NULL, 1),
(7173831, 1101236, 114285, '<td valign="top">Sure is 8</td>', 'Sure is 8', '2014-02-10 01:53:23.000000', NULL, 1),
(7173884, 1101317, 111084, '<td valign="top">Excellent, my choice!</td>', 'Excellent, my choice!', '2014-02-10 05:22:14.000000', NULL, 1),
(7174017, 1101335, 144365, '<td valign="top">Do trees naturally have halos around them where you''re from?</td>', 'Do trees naturally have halos around them where you''re from?', '2014-02-10 10:12:04.000000', NULL, 1),
(7174021, 1101453, 30669, '<td valign="top">Very Nice.</td>', 'Very Nice.', '2014-02-10 10:16:23.000000', NULL, 1),
(7174157, 1101402, 173844, '<td valign="top">Confidently, assertively minimal.  The detailed tracery of the cypress seems to lord over an empty world; yet the soft waves of the water''s surface offer plenty of quiet detail as the horizon disappears.  Wonderful tonal control.  Beautiful image.</td>', 'Confidently, assertively minimal.  The detailed tracery of the cypress seems to lord over an empty world; yet the soft waves of the water''s surface offer plenty of quiet detail as the horizon disappears.  Wonderful tonal control.  Beautiful image.', '2014-02-10 15:05:27.000000', NULL, 1),
(7174163, 1101233, 173844, '<td valign="top">The stalks in the snow-covered field are launched out of dullness by their pattern of rows, capped by the trees on the horizon line.  Clever observation.  So I think this image is very sophisticated and interesting.</td>', 'The stalks in the snow-covered field are launched out of dullness by their pattern of rows, capped by the trees on the horizon line.  Clever observation.  So I think this image is very sophisticated and interesting.', '2014-02-10 15:11:38.000000', NULL, 1),
(7174170, 1101335, 173844, '<td valign="top">A beautiful picture made so by magical lighting and pleasing composition.  Makes a wonderful case for winter.</td>', 'A beautiful picture made so by magical lighting and pleasing composition.  Makes a wonderful case for winter.', '2014-02-10 15:18:25.000000', NULL, 1),
(7174176, 1101438, 173844, '<td valign="top">Gorgeous minimalism, a new category.  The physical features, aside from the water, are certainly in the realm of traditional minimalism.  They, mysterious and peripheral as they are, still serve to anchor the image in "reality."  Going into my favorites.</td>', 'Gorgeous minimalism, a new category.  The physical features, aside from the water, are certainly in the realm of traditional minimalism.  They, mysterious and peripheral as they are, still serve to anchor the image in "reality."  Going into my favorites.', '2014-02-10 15:30:40.000000', NULL, 1),
(7174177, 1101425, 173844, '<td valign="top">I guess it''s a matter of taste and opinion whether or not minimalism must exclude strong colors.  Don''t think so.  This, my favorite image in the challenge, is physically spare, which is the main requirement, again in my opinion.  The clear, bell-like notes of color, in fact, make this image so appealing.  Beautiful and joyous.  Going into my favorites.</td>', 'I guess it''s a matter of taste and opinion whether or not minimalism must exclude strong colors.  Don''t think so.  This, my favorite image in the challenge, is physically spare, which is the main requirement, again in my opinion.  The clear, bell-like notes of color, in fact, make this image so appealing.  Beautiful and joyous.  Going into my favorites.', '2014-02-10 15:31:19.000000', NULL, 1),
(7174178, 1101463, 173844, '<td valign="top">Not sure what''s going on here, but I find it pleasing and intriguing.  The strong sun casts confusion over the photo.  Even the contrails work.  Well worth lingering over.</td>', 'Not sure what''s going on here, but I find it pleasing and intriguing.  The strong sun casts confusion over the photo.  Even the contrails work.  Well worth lingering over.', '2014-02-10 15:49:11.000000', NULL, 1),
(7174183, 1101290, 173844, '<td valign="top">Strikingly minimal.  The contrast between the strongly detailed pilings and the soft background create the interest.  Very, very attractive.  Alternate title --  Neptune''s Fork.</td>', 'Strikingly minimal.  The contrast between the strongly detailed pilings and the soft background create the interest.  Very, very attractive.  Alternate title --  Neptune''s Fork.', '2014-02-10 16:03:09.000000', NULL, 1),
(7174209, 1101184, 34481, '<td valign="top">Definitely one of my favorites.  I would have liked to see a little more sky and a little less foreground I think.  Beautiful clouds not over processed.  Beautiful symmetry to the peaks.  B/W really works well.</td>', 'Definitely one of my favorites.  I would have liked to see a little more sky and a little less foreground I think.  Beautiful clouds not over processed.  Beautiful symmetry to the peaks.  B/W really works well.', '2014-02-10 17:22:27.000000', NULL, 1),
(7174210, 1101316, 34481, '<td valign="top">One of my favorites.  Dark brooding b/w really works. I would have liked to see a tiny bit more water.</td>', 'One of my favorites.  Dark brooding b/w really works. I would have liked to see a tiny bit more water.', '2014-02-10 17:24:03.000000', NULL, 1),
(7174211, 1101360, 34481, '<td valign="top">beautiful image.</td>', 'beautiful image.', '2014-02-10 17:24:49.000000', NULL, 1),
(7174214, 1101453, 34481, '<td valign="top">I would say this is not exactly a pleasant image to look at, but it is really interesting and it catches my attention.  The small figure really gives it perspective and focus.  Without the figure it would not work at all.  I love the snow in the dark sky.</td>', 'I would say this is not exactly a pleasant image to look at, but it is really interesting and it catches my attention.  The small figure really gives it perspective and focus.  Without the figure it would not work at all.  I love the snow in the dark sky.', '2014-02-10 17:26:45.000000', NULL, 1),
(7174219, 1101290, 34481, '<td valign="top">One of my favorites in the challenge.  The composition is spot on.  I love the subdued muted background and the strong contrasting tones of the posts and shadows.</td>', 'One of my favorites in the challenge.  The composition is spot on.  I love the subdued muted background and the strong contrasting tones of the posts and shadows.', '2014-02-10 17:33:37.000000', NULL, 1),
(7174221, 1100895, 34481, '<td valign="top">This composition really works for me.  You caught a really nice sky.  Nice post processing.  Meets the minimalist standards nicely.  Definitely a something I would like to hang on my wall.</td>', 'This composition really works for me.  You caught a really nice sky.  Nice post processing.  Meets the minimalist standards nicely.  Definitely a something I would like to hang on my wall.', '2014-02-10 17:35:26.000000', NULL, 1),
(7174223, 1101307, 34481, '<td valign="top">One of my favorites.  I love the islands.  Not so sure about the rock in the foreground.  You might have played around with a little longer time exposure to blur the moving clouds a bit more.  I love the sheen and subtle tones in the water.</td>', 'One of my favorites.  I love the islands.  Not so sure about the rock in the foreground.  You might have played around with a little longer time exposure to blur the moving clouds a bit more.  I love the sheen and subtle tones in the water.', '2014-02-10 17:37:11.000000', NULL, 1),
(7174224, 1101335, 34481, '<td valign="top">Great composition and post processing.  One of my favorites.</td>', 'Great composition and post processing.  One of my favorites.', '2014-02-10 17:37:48.000000', NULL, 1),
(7174225, 1101493, 34481, '<td valign="top">One of my favorites. I love the strong horizontal lighting and the abstract qualities.  Fits the challenge nicely.</td>', 'One of my favorites. I love the strong horizontal lighting and the abstract qualities.  Fits the challenge nicely.', '2014-02-10 17:38:46.000000', NULL, 1),
(7174226, 1101452, 34481, '<td valign="top">great composition.  one of my favorites.</td>', 'great composition.  one of my favorites.', '2014-02-10 17:39:24.000000', NULL, 1),
(7174227, 1101370, 34481, '<td valign="top">Unique image that fits the challenge nicely.  One of my favorites.</td>', 'Unique image that fits the challenge nicely.  One of my favorites.', '2014-02-10 17:40:02.000000', NULL, 1),
