INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7175478, 1100895, 96751, '<td valign="top">Congrats!  Love the splash of red</td>', 'Congrats!  Love the splash of red', '2014-02-12 22:06:28.000000', NULL, 0),
(7175484, 1100895, 19825, '<td valign="top">Fantastic shot, Janine. Great composition and deftly processed.</td>', 'Fantastic shot, Janine. Great composition and deftly processed.', '2014-02-12 22:27:25.000000', NULL, 0),
(7175490, 1101351, 114285, '<td valign="top">I was meaning to comment on this, thought it was just a wonderful image.</td>', 'I was meaning to comment on this, thought it was just a wonderful image.', '2014-02-12 23:05:56.000000', NULL, 0),
(7175491, 1101280, 114285, '<td valign="top">minimal, ummm, I don''t think so!</td>', 'minimal, ummm, I don''t think so!', '2014-02-12 23:06:53.000000', NULL, 0),
(7175494, 1101316, 114285, '<td valign="top">Did any of us have a chance :)<br/> <br/>I''m going to remember this when we go to Hawaii, soon :)</td>', 'Did any of us have a chance :) I''m going to remember this when we go to Hawaii, soon :)', '2014-02-12 23:11:24.000000', NULL, 0),
(7175557, 1100895, 113411, '<td valign="top">fabulous work, Janine! Congratulations!!!!</td>', 'fabulous work, Janine! Congratulations!!!!', '2014-02-13 00:57:34.000000', NULL, 0),
(7175733, 1101225, 108991, '<td valign="top">It seems that my vision on landscape is not shared by this community. One of your 10s is by me. And I ended very low myself.<br/> <br/>I still love yours and don''t have a clue what I am looking at :-))</td>', 'It seems that my vision on landscape is not shared by this community. One of your 10s is by me. And I ended very low myself. I still love yours and don''t have a clue what I am looking at :-))', '2014-02-13 11:21:33.000000', NULL, 0),
(7175738, 1100846, 108991, '<td valign="top">Wonderful, silvery light; great tonal scale, superb colours. You deserved a much higher place.</td>', 'Wonderful, silvery light; great tonal scale, superb colours. You deserved a much higher place.', '2014-02-13 11:23:57.000000', NULL, 0),
(7175792, 1101237, 74559, '<td valign="top">Congrats on the top ten, Deb!</td>', 'Congrats on the top ten, Deb!', '2014-02-13 13:14:38.000000', NULL, 0),
(7175941, 1100712, 173844, '<td valign="top">I hadn''t time to comment earlier.  Fine image that''s more than just a tree.  The pattern of stakes makes a very interesting transition between the foreground grass and the delicate horizon line of trees.  Very nice.</td>', 'I hadn''t time to comment earlier.  Fine image that''s more than just a tree.  The pattern of stakes makes a very interesting transition between the foreground grass and the delicate horizon line of trees.  Very nice.', '2014-02-13 17:13:56.000000', NULL, 0),
(7175943, 1101316, 173844, '<td valign="top">Congratulations on winning the blue for this astounding image.  Two heartbeats and an expansive spirit.</td>', 'Congratulations on winning the blue for this astounding image.  Two heartbeats and an expansive spirit.', '2014-02-13 17:15:29.000000', NULL, 0),
(7175945, 1101367, 173844, '<td valign="top">Congratulations on taking the red.  An awesome sky, a sliver of land and a very important tree limb.</td>', 'Congratulations on taking the red.  An awesome sky, a sliver of land and a very important tree limb.', '2014-02-13 17:18:55.000000', NULL, 0),
(7175950, 1100895, 173844, '<td valign="top">Congratulations on winning the yellow.  I didn''t have time to comment on this image earlier.  The combination of colors here is beautiful and the red is pitch perfect.  The horizontal striping effect, politely interrupted by the red structure, is quietly compelling.  And so peaceful.</td>', 'Congratulations on winning the yellow.  I didn''t have time to comment on this image earlier.  The combination of colors here is beautiful and the red is pitch perfect.  The horizontal striping effect, politely interrupted by the red structure, is quietly compelling.  And so peaceful.', '2014-02-13 17:33:16.000000', NULL, 0),
(7175959, 1101453, 173844, '<td valign="top">I didn''t have time to comment on this during the challenge.  I like this rugged image with the lake as chopped up and chaotic as the shore.  I like the bluish cast to the lake ice and the perfectly placed figure (w/o any blue cast).  No compromises here.</td>', 'I didn''t have time to comment on this during the challenge.  I like this rugged image with the lake as chopped up and chaotic as the shore.  I like the bluish cast to the lake ice and the perfectly placed figure (w/o any blue cast).  No compromises here.', '2014-02-13 18:00:27.000000', NULL, 0),
(7175962, 1101397, 173844, '<td valign="top">Didn''t get to comment on this during the challenge.  So very minimal, but for the windswept patterns in the snow and the bird and the tiny structure on the distant horizon.  Powerful expression of nature''s vastness.  Makes one appreciate the coziness of home.</td>', 'Didn''t get to comment on this during the challenge.  So very minimal, but for the windswept patterns in the snow and the bird and the tiny structure on the distant horizon.  Powerful expression of nature''s vastness.  Makes one appreciate the coziness of home.', '2014-02-13 18:06:39.000000', NULL, 0),
(7175966, 1101425, 173844, '<td valign="top">How''d this beauty seem to escape notice?</td>', 'How''d this beauty seem to escape notice?', '2014-02-13 18:13:55.000000', NULL, 0),
(7175968, 1101423, 173844, '<td valign="top">Didn''t get to comment on this during the challenge.  Wonderfully successful take on minimalism.  Even with so much fine textural detail, this image easily can be seen as a fascinating abstract.  Maybe this was too minimal for some.</td>', 'Didn''t get to comment on this during the challenge.  Wonderfully successful take on minimalism.  Even with so much fine textural detail, this image easily can be seen as a fascinating abstract.  Maybe this was too minimal for some.', '2014-02-13 18:18:39.000000', NULL, 0),
(7175970, 1101447, 173844, '<td valign="top">Lovely, delicate, magical.  So like a watercolor.</td>', 'Lovely, delicate, magical.  So like a watercolor.', '2014-02-13 18:21:11.000000', NULL, 0),
(7176228, 1100895, 69008, '<td valign="top">Beautiful sky Janine, and it''s easy to understand why there are no people there.  I like the whole combination of things in this image.  Congrats on the new ribbon!</td>', 'Beautiful sky Janine, and it''s easy to understand why there are no people there.  I like the whole combination of things in this image.  Congrats on the new ribbon!', '2014-02-13 22:49:27.000000', NULL, 0),
(7176375, 1101237, 96751, '<td valign="top">Look at you on the front page!!!  LOVE this. The sun really worked for you.</td>', 'Look at you on the front page!!!  LOVE this. The sun really worked for you.', '2014-02-14 01:34:36.000000', NULL, 0),
(7176376, 1101402, 96751, '<td valign="top">Even the waves are minimal.  Love it, Wendy. Congrats on the HM</td>', 'Even the waves are minimal.  Love it, Wendy. Congrats on the HM', '2014-02-14 01:36:20.000000', NULL, 0),
(7176378, 1101289, 96751, '<td valign="top">Crunchy. Beautifully punctuated.</td>', 'Crunchy. Beautifully punctuated.', '2014-02-14 01:37:18.000000', NULL, 0),
(7176397, 1101367, 86218, '<td valign="top">Nicely done Alex.. There is no such thing as bad weather in photography. Congrats</td>', 'Nicely done Alex.. There is no such thing as bad weather in photography. Congrats', '2014-02-14 02:57:39.000000', NULL, 0),
(7176450, 1101289, 93565, '<td valign="top">I really like the subtlety of the colors.</td>', 'I really like the subtlety of the colors.', '2014-02-14 07:50:43.000000', NULL, 0),
(7177238, 1101317, 173844, '<td valign="top">Didn''t get to comment on this image during the challenge.  It''s amazing how much life you''ve wrung out of this barren scene.  The tree is stalwart, the bird is jauntily perched and there''s more going on up above.  I like the way the water merges foggily into the gray sky.  Every bit of open space is worth its presence.</td>', 'Didn''t get to comment on this image during the challenge.  It''s amazing how much life you''ve wrung out of this barren scene.  The tree is stalwart, the bird is jauntily perched and there''s more going on up above.  I like the way the water merges foggily into the gray sky.  Every bit of open space is worth its presence.', '2014-02-15 21:50:25.000000', NULL, 0),
(7177246, 1100949, 173844, '<td valign="top">Didn''t get to comment on this image earlier.  I like how these simple elements work together.  There are two hillsides. The smaller background hill, which is the more brightly lit of the pair, nicely balances the larger, darker foreground hill and its group of trees.  The beautifully colored sky embraces them both.  Very serene.</td>', 'Didn''t get to comment on this image earlier.  I like how these simple elements work together.  There are two hillsides. The smaller background hill, which is the more brightly lit of the pair, nicely balances the larger, darker foreground hill and its group of trees.  The beautifully colored sky embraces them both.  Very serene.', '2014-02-15 22:03:24.000000', NULL, 0),
(7177248, 1101179, 173844, '<td valign="top">Didn''t get to comment on this image earlier.  I admire how with such minimal information so much is suggested and alluded to.  In revisiting, I wish I had given this a 10 instead of a foolishly hasty 7.</td>', 'Didn''t get to comment on this image earlier.  I admire how with such minimal information so much is suggested and alluded to.  In revisiting, I wish I had given this a 10 instead of a foolishly hasty 7.', '2014-02-15 22:10:56.000000', NULL, 0),
(7177249, 1100449, 173844, '<td valign="top">I didn''t get to comment on this image earlier.  Aside from post-processing issues, which I hadn''t noticed, I like this image.  The lighting brings out considerable delicate detail in both the grasses of the foreground and the clouds of the background, while nicely allowing the midground to go to silhouette.</td>', 'I didn''t get to comment on this image earlier.  Aside from post-processing issues, which I hadn''t noticed, I like this image.  The lighting brings out considerable delicate detail in both the grasses of the foreground and the clouds of the background, while nicely allowing the midground to go to silhouette.', '2014-02-15 22:18:51.000000', NULL, 0),
(7177250, 1101351, 173844, '<td valign="top">Didn''t get to comment on this image earlier.  The imaginative framing is what makes this shot.  The combination of minimal natural (the foreground vegetation) and the minimal man-made (the cropped swing set) adds up to way more than the sum of its parts.  The texture of the snow ties it all together, and the glimpse of the staircase is a quirky bonus.</td>', 'Didn''t get to comment on this image earlier.  The imaginative framing is what makes this shot.  The combination of minimal natural (the foreground vegetation) and the minimal man-made (the cropped swing set) adds up to way more than the sum of its parts.  The texture of the snow ties it all together, and the glimpse of the staircase is a quirky bonus.', '2014-02-15 22:28:03.000000', NULL, 0),
(7177294, 1101443, 22459, '<td valign="top">Funny!!</td>', 'Funny!!', '2014-02-16 06:03:22.000000', NULL, 0),
(7177337, 1100895, 70661, '<td valign="top">WOW!</td>', 'WOW!', '2014-02-16 11:28:07.000000', NULL, 0),
(7177401, 1101316, 30214, '<td valign="top">Congrats Mark! beautiful shot, the only thing that slightly bugs me is a thin white halo around the islands - sharpening? could''ve easily cloned it out I guess...</td>', 'Congrats Mark! beautiful shot, the only thing that slightly bugs me is a thin white halo around the islands - sharpening? could''ve easily cloned it out I guess...', '2014-02-16 17:52:27.000000', NULL, 0),
(7177526, 1101402, 30982, '<td valign="top">I liked it enough to give it an 8, and I don''t give out very many of those.  Seems everyone was pretty happy with it being a landscape!</td>', 'I liked it enough to give it an 8, and I don''t give out very many of those.  Seems everyone was pretty happy with it being a landscape!', '2014-02-16 21:20:26.000000', NULL, 0),
(7177549, 1101438, 93565, '<td valign="top">A lot of cool things going on here. I really like the red, and the figure in the background, but the textures are also really cool and varied.</td>', 'A lot of cool things going on here. I really like the red, and the figure in the background, but the textures are also really cool and varied.', '2014-02-16 22:24:33.000000', NULL, 0),
(7177551, 1101423, 93565, '<td valign="top">I don''t have a terribly detailed comment for this other than that I like it for a lot of reasons.</td>', 'I don''t have a terribly detailed comment for this other than that I like it for a lot of reasons.', '2014-02-16 22:28:27.000000', NULL, 0),
(7177572, 1101172, 93565, '<td valign="top">I very much enjoy and appreciate this. I don''t feel like you need to alter it in any way. I really like that you''ve gone in such a different but valid direction with things here.</td>', 'I very much enjoy and appreciate this. I don''t feel like you need to alter it in any way. I really like that you''ve gone in such a different but valid direction with things here.', '2014-02-16 22:37:56.000000', NULL, 0),
(7178166, 1101365, 174623, '<td valign="top">Gorgeous photo!</td>', 'Gorgeous photo!', '2014-02-17 18:24:05.000000', NULL, 0),
(7179628, 1101154, 16148, '<td valign="top">I just stumbled on your image.  Terrific photograph although I''m mixed on the heavy vignette.  At first I thought it''s to strong but now I''m not sure.  The heavy vignette does repeat the shape of the island of trees.  Anyway, I find this very interesting.  Thanks.</td>', 'I just stumbled on your image.  Terrific photograph although I''m mixed on the heavy vignette.  At first I thought it''s to strong but now I''m not sure.  The heavy vignette does repeat the shape of the island of trees.  Anyway, I find this very interesting.  Thanks.', '2014-02-21 09:30:26.000000', NULL, 0),
(7213971, 1100895, 108580, '<td valign="top">Classic image and lovely PP in a soft and dreamy dreary summer way.</td>', 'Classic image and lovely PP in a soft and dreamy dreary summer way.', '2014-05-07 15:36:01.000000', NULL, 0),
(7230723, 1101354, 23484, '<td valign="top">It''s so barren looking. Nice job.</td>', 'It''s so barren looking. Nice job.', '2014-06-18 21:07:08.000000', NULL, 0),
(7248248, 1101439, 119419, '<td valign="top">I see a macro of a cicada wing, very beautiful.</td>', 'I see a macro of a cicada wing, very beautiful.', '2014-08-06 20:16:21.000000', NULL, 0),
(7373963, 1101438, 30982, '<td valign="top">This is really nice!</td>', 'This is really nice!', '2015-06-27 02:40:38.000000', NULL, 0),
(7507632, 1101237, 80058, '<td valign="top">Stunning shot!</td>', 'Stunning shot!', '2017-04-04 10:44:27.000000', NULL, 0);
